    pair.server_conn_mut(server_ch).set_receive_window(50u32.into());
    pair.server_conn_mut(server_ch).set_receive_window(100u32.into());
    pair.drive();
    let s = pair.client_streams(client_ch).open(Dir::Uni).unwrap();
    assert_eq!(pair.client_send(client_ch, s).write(&[0; 200]), Ok(100),
        "without any reads, the peer should have only the original 100-byte receive window");
